using Htt.Infrastructure;
using Htt.SharedKernel;
using Htt.Host.Api.MasterData;
using NpgsqlTypes;
using static Htt.Host.Api.MasterData.MasterDataSupport;
using static Htt.Host.Api.Sales.SalesSupport;
namespace Htt.Host.Api.Accounting;
public sealed record StatementPeriodInput(DateOnly From,DateOnly To);
public sealed record OperatingReportInput(string Kind,DateOnly From,DateOnly To,Guid? PartyId=null,Guid? WarehouseId=null,Guid? BankAccountId=null);
internal static class OperatingReportEndpoints
{
 private static void Range(DateOnly from,DateOnly to)=>Check.That(from.Year>=2&&to>from&&to.DayNumber-from.DayNumber<=366,"range","Use a half-open interval of 1..366 days.");
 private static OperatingReportInput Validate(OperatingReportInput x){Range(x.From,x.To);Check.OneOf(x.Kind,"kind","PURCHASING","ARAP","INVENTORY","BANKING");Check.That((x.PartyId is null||x.Kind is "PURCHASING" or "ARAP")&&(x.WarehouseId is null||x.Kind=="INVENTORY")&&(x.BankAccountId is null||x.Kind=="BANKING"),"filters","A filter is only accepted by its report family.");return x;}
 private static DbArg[] Args(OperatingReportInput x)=>[new("kind",x.Kind),new("from",x.From),new("to",x.To),new("party",x.PartyId,NpgsqlDbType.Uuid),new("warehouse",x.WarehouseId,NpgsqlDbType.Uuid),new("bank",x.BankAccountId,NpgsqlDbType.Uuid)];
 private static Task<List<Dictionary<string,object?>>> Authorize(CompanySession s,Guid id,string action,CancellationToken ct)=>Read(s,"SELECT platform.require_document_access(@id,@action)",ct,new DbArg("id",id),new DbArg("action",action));
 private static async Task<object> Statement(CompanySession s,Guid id,CancellationToken ct)
 {var row=await One(s,"SELECT id,customer_id,snapshot::text,sha256,created_at FROM accounting.customer_statements WHERE company_id=@company AND id=@id",ct,new DbArg("id",id));await Authorize(s,id,"READ",ct);return new{id,version=1,customerId=row["customer_id"],snapshot=Element(row["snapshot"]!),sha256=row["sha256"],createdAt=row["created_at"]};}
 private static async Task<Dictionary<string,object?>> Run(CompanySession s,Guid id,CancellationToken ct)
 {var row=await One(s,"SELECT r.*,d.version FROM accounting.operating_report_runs r JOIN platform.documents d ON d.company_id=r.company_id AND d.id=r.id WHERE r.company_id=@company AND r.id=@id",ct,new DbArg("id",id));await Read(s,"SELECT accounting.require_operating_report(@kind)",ct,new DbArg("kind",row["kind"]));return row;}
 public static void Map(RouteGroupBuilder g)
 {
  g.MapGet("/customers/{id:guid}/statement-preview",async(Guid id,DateOnly from,DateOnly to,CompanySession s,CancellationToken ct)=>{Range(from,to);return Results.Content((string)(await One(s,"SELECT accounting.statement_snapshot(@id,@from,@to)::text AS result",ct,new DbArg("id",id),new DbArg("from",from),new DbArg("to",to)))["result"]!,"application/json");}).WithMetadata(new Permission("accounting.statements.read"));
  g.MapPost("/customers/{id:guid}/statements",CaptureStatement).WithMetadata(new Permission("accounting.statements.read"));
  g.MapGet("/customer-statements/{id:guid}",async(Guid id,CompanySession s,CancellationToken ct)=>Results.Ok(await Statement(s,id,ct))).WithMetadata(new Permission("accounting.statements.read"));
  g.MapGet("/customers/{id:guid}/statements",async(Guid id,int? page,int? pageSize,CompanySession s,CancellationToken ct)=>{await Read(s,"SELECT accounting.require_statement_customer(@id)",ct,new DbArg("id",id));var(offset,size)=Page(page,pageSize);return Results.Ok(new{items=(await Read(s,"SELECT id,from_date,to_date,sha256,created_at,created_by FROM accounting.customer_statements WHERE company_id=@company AND customer_id=@id ORDER BY created_at DESC,id LIMIT @size OFFSET @offset",ct,new DbArg("id",id),new DbArg("size",size),new DbArg("offset",offset))).Select(PublicRow),page=page??1,pageSize=size});}).WithMetadata(new Permission("accounting.statements.read"));
  g.MapGet("/accounting/reports/operating",async(string kind,DateOnly from,DateOnly to,Guid? partyId,Guid? warehouseId,Guid? bankAccountId,int? page,int? pageSize,CompanySession s,CancellationToken ct)=>{var x=Validate(new(kind,from,to,partyId,warehouseId,bankAccountId));var(offset,size)=Page(page,pageSize);return Results.Content((string)(await One(s,"WITH report AS MATERIALIZED(SELECT accounting.operating_report(@kind,@from,@to,@party,@warehouse,@bank)AS body)SELECT(body-'rows'||jsonb_build_object('totalCount',jsonb_array_length(body->'rows'),'page',@page,'pageSize',@size,'rows',coalesce((SELECT jsonb_agg(e ORDER BY n)FROM jsonb_array_elements(body->'rows')WITH ORDINALITY z(e,n)WHERE n>@offset AND n<=@offset+@size),'[]'::jsonb)))::text AS result FROM report",ct,[..Args(x),new("page",page??1),new("size",size),new("offset",offset)]))["result"]!,"application/json");}).WithMetadata(new Permission("reports.operating.read"));
  g.MapGet("/operating-report-runs",async(string kind,int? page,int? pageSize,CompanySession s,CancellationToken ct)=>{Check.OneOf(kind,"kind","PURCHASING","ARAP","INVENTORY","BANKING");await Read(s,"SELECT accounting.require_operating_report(@kind)",ct,new DbArg("kind",kind));var(offset,size)=Page(page,pageSize);return Results.Ok(new{items=(await Read(s,"SELECT id,kind,from_date,to_date,sha256,created_at,created_by FROM accounting.operating_report_runs WHERE company_id=@company AND kind=@kind ORDER BY created_at DESC,id LIMIT @size OFFSET @offset",ct,new DbArg("kind",kind),new DbArg("size",size),new DbArg("offset",offset))).Select(PublicRow),page=page??1,pageSize=size});}).WithMetadata(new Permission("reports.operating.read"));
  g.MapPost("/operating-report-runs",CaptureReport).WithMetadata(new Permission("reports.operating.read"));
  g.MapGet("/operating-report-runs/{id:guid}",async(Guid id,CompanySession s,CancellationToken ct)=>{var row=await Run(s,id,ct);return Results.Ok(new{id,version=row["version"],kind=row["kind"],snapshot=Element(row["snapshot"]!),sha256=row["sha256"],createdAt=row["created_at"]});}).WithMetadata(new Permission("reports.operating.read"));
  g.MapPost("/operating-report-runs/{id:guid}/export",Export).WithMetadata(new Permission("reports.operating.export"));
 }
 private static async Task<IResult> CaptureStatement(Guid id,StatementPeriodInput x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {Range(x.From,x.To);await Read(s,"SELECT accounting.require_statement_customer(@id)",ct,new DbArg("id",id));var result=await idem.ExecuteAsync($"POST /customers/{id}/statements",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,x}),async()=>{var sid=(Guid)(await One(s,"SELECT accounting.capture_statement(@id,@from,@to)AS id",ct,new DbArg("id",id),new DbArg("from",x.From),new DbArg("to",x.To)))["id"]!;await Sql.AuditAsync(s,"accounting.statement_captured","customer_statement",sid,h.TraceIdentifier,ct);return ApiJson.Stored(await Statement(s,sid,ct),201);},ct);return ApiJson.Result(result);}
 private static async Task<IResult> CaptureReport(OperatingReportInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {var x=Validate(input);await Read(s,"SELECT accounting.require_operating_report(@kind)",ct,new DbArg("kind",x.Kind));var result=await idem.ExecuteAsync("POST /operating-report-runs",h.Request.Headers["Idempotency-Key"].ToString(),Json(x),async()=>{var id=(Guid)(await One(s,"SELECT accounting.capture_operating_report(@kind,@from,@to,@party,@warehouse,@bank)AS id",ct,Args(x)))["id"]!;await Sql.AuditAsync(s,"reports.operating_captured","operating_report",id,h.TraceIdentifier,ct);var row=await Run(s,id,ct);return ApiJson.Stored(new{id,version=row["version"],sha256=row["sha256"],snapshot=Element(row["snapshot"]!)},201);},ct);return ApiJson.Result(result);}
 private static async Task<IResult> Export(Guid id,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {await Run(s,id,ct);await Authorize(s,id,"EXPORT",ct);var version=Version(h);var result=await idem.ExecuteAsync($"POST /operating-report-runs/{id}/export",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,version}),async()=>{Check.That(version==1,"version","Frozen report version is 1.");var payload=(string)(await One(s,"SELECT accounting.report_export_payload(@id)::text AS payload",ct,new DbArg("id",id)))["payload"]!;var jobs=await Read(s,"INSERT INTO platform.document_jobs(company_id,document_id,source_version,kind,payload,created_by)VALUES(@company,@id,1,'EXPORT',@payload,@actor)ON CONFLICT(company_id,document_id,source_version)WHERE kind='EXPORT'DO NOTHING RETURNING id",ct,new DbArg("id",id),new DbArg("payload",payload,NpgsqlDbType.Jsonb));var job=jobs.Count>0?(Guid)jobs[0]["id"]!:(Guid)(await One(s,"SELECT id FROM platform.document_jobs WHERE company_id=@company AND document_id=@id AND source_version=1 AND kind='EXPORT'",ct,new DbArg("id",id)))["id"]!;if(jobs.Count>0)await Sql.AuditAsync(s,"reports.export_requested","document_job",job,h.TraceIdentifier,ct,new{reportId=id});return ApiJson.Stored(new{id=job,documentId=id,sourceVersion=1},202);},ct);return ApiJson.Result(result);}
}
